import React from 'react';
import { AUDIENCES, setAudience } from '../utils/audience';
import axios from 'axios';

export default function AudienceGate(){
  const choose = (v) => {
    setAudience(v);
    axios.defaults.headers.common['X-Audience'] = v;
    const el = document.querySelector('.ag-root');
    if(el){ el.classList.add('chosen'); }
    setTimeout(()=>{ window.location.href='/'; }, 250);
  };
  return (
    <div className="ag-root">
      <img className="ag-logo" src="/logo.png" alt="Conecta Pinamar"/>
      <div className="ag-split">
        <button className="ag-side left" onClick={()=>choose(AUDIENCES.RESIDENT)}>
          <div className="ag-label">SOY RESIDENTE</div>
        </button>
        <button className="ag-side right" onClick={()=>choose(AUDIENCES.TOURIST)}>
          <div className="ag-label">SOY TURISTA</div>
        </button>
      </div>
    </div>
  );
}
